//--------------------------------------------------------------------------//

void sense_rs_can_glowplug_init( void )
{
    
}	

//--------------------------------------------------------------------------//

Boolean sense_rs_glowplug_off_can( Boolean instant_level )
{
    sense_glowplug( instant_level || !get_ign_status() );                

    return get_glowplug_off_status();
}
    

//--------------------------------------------------------------------------//

void sense_glowplug( Boolean instant_level )
{
    SInt8 edge_detect ; 

	Boolean old_status = get_glowplug_off_status();

	set_glowplug_off_data_status( instant_level ); 
			
	if( old_status != get_glowplug_off_status() )
	{	    			
	    cmd_q_insert( get_glowplug_off_status() ? INPUT_GLOWPLUG_STATUS_OFF : INPUT_GLOWPLUG_STATUS_ON , SENSE_RS_CAN_TIMEOUT_CMD_Q);

		TRACE_SENSE_RS_CAN("\n\r[GLOWPLUG %s]\n\r" , get_glowplug_off_status() ? "OFF":"ON" );		        
    }
}

